package intersect.oracle;
import java.io.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.util.*;import org.eclipse.emf.common.util.URI;import org.eclipse.emf.ecore.*;import org.eclipse.xtext.*;import org.eclipse.xtext.parser.IParser;import org.eclipse.xtext.resource.XtextResourceSet;import org.eclipse.xtext.nodemodel.util.NodeModelUtils;import org.antlr.runtime.*;import org.eclipse.xtext.validation.*;import org.eclipse.xtext.util.CancelIndicator;
public class FullRuntime {
 static Map<String,Object> fields(Object... values){return TerminalNegationOracle.fields(values);}
 static Object failure(Throwable t){List<Object> chain=new ArrayList<>();for(Throwable c=t;c!=null;c=c.getCause())chain.add(fields("class",c.getClass().getName(),"message",c.getMessage()));return chain;}
 public static void main(String[] args)throws Exception{
  for(String name:args[0].split(",")){var p=(EPackage)Class.forName(name).getField("eINSTANCE").get(null);EPackage.Registry.INSTANCE.put(p.getNsURI(),p);}
  var setup=(ISetup)Class.forName(args[1]+"StandaloneSetup").getConstructor().newInstance();var injector=setup.createInjectorAndDoEMFRegistration();String text=new String(Base64.getDecoder().decode(args[2]),StandardCharsets.UTF_8);
  Map<String,Object> result=fields("text",text,"lexer",null,"resource",null,"parser",null);
  try{var lexer=injector.getInstance(org.eclipse.xtext.parser.antlr.Lexer.class);lexer.setCharStream(new ANTLRStringStream(text));Map<Integer,String> names=new TreeMap<>();for(var f:lexer.getClass().getFields())if(f.getType()==int.class&&java.lang.reflect.Modifier.isStatic(f.getModifiers())&&(f.getName().startsWith("RULE_")||f.getName().startsWith("T__")))names.put(f.getInt(null),f.getName());List<Object> tokens=new ArrayList<>();boolean complete=false;for(int n=0;n<text.length()+4;n++){var t=(CommonToken)lexer.nextToken();tokens.add(fields("type",t.getType(),"name",t.getType()==Token.EOF?"EOF":names.get(t.getType()),"text",t.getText(),"utf16_start",t.getStartIndex(),"utf16_stop",t.getStopIndex(),"channel",t.getChannel()));if(t.getType()==Token.EOF){complete=true;break;}}result.put("lexer",fields("tokens",tokens,"through_eof",complete,"antlr_syntax_error_count",lexer.getNumberOfSyntaxErrors(),"failure",null));}catch(Throwable t){result.put("lexer",fields("failure",failure(t)));}
  org.eclipse.emf.ecore.resource.Resource resource=null;
  try{var resources=injector.getInstance(XtextResourceSet.class);resource=resources.createResource(URI.createURI("memory:/model.lexicaltest"));resource.load(new ByteArrayInputStream(text.getBytes(StandardCharsets.UTF_8)),null);List<Object> errors=new ArrayList<>();for(var d:resource.getErrors())errors.add(fields("message",d.getMessage(),"line",d.getLine(),"column",d.getColumn()));List<Object> warnings=new ArrayList<>();for(var d:resource.getWarnings())warnings.add(fields("message",d.getMessage(),"line",d.getLine(),"column",d.getColumn()));var root=resource.getContents().isEmpty()?null:resource.getContents().get(0);List<Object> leaves=new ArrayList<>();if(root!=null){var node=NodeModelUtils.getNode(root);if(node!=null)for(var leaf:node.getLeafNodes())leaves.add(fields("text",leaf.getText(),"hidden",leaf.isHidden(),"utf16_start",leaf.getOffset(),"utf16_end",leaf.getEndOffset(),"syntax_error",leaf.getSyntaxErrorMessage()==null?null:leaf.getSyntaxErrorMessage().getMessage()));}result.put("resource",fields("accepted",root!=null&&errors.isEmpty(),"errors",errors,"warnings",warnings,"resource_contents",resource.getContents().size(),"model",RuntimeOracle.model(root),"leaves",leaves,"failure",null));}catch(Throwable t){result.put("resource",fields("accepted",false,"failure",failure(t),"resource_contents",resource==null?null:resource.getContents().size(),"model",resource==null||resource.getContents().isEmpty()?null:RuntimeOracle.model(resource.getContents().get(0))));}
  try{var grammar=injector.getInstance(IGrammarAccess.class).getGrammar();var rule=(ParserRule)GrammarUtil.findRuleForName(grammar,"Model");var parsed=injector.getInstance(IParser.class).parse(rule,new StringReader(text));List<Object> errors=new ArrayList<>();for(var n:parsed.getSyntaxErrors())errors.add(fields("message",n.getSyntaxErrorMessage().getMessage(),"utf16_start",n.getOffset(),"utf16_end",n.getEndOffset()));var root=parsed.getRootASTElement();result.put("parser",fields("accepted",root!=null&&errors.isEmpty(),"errors",errors,"model",RuntimeOracle.model(root),"failure",null));}catch(Throwable t){result.put("parser",fields("accepted",false,"failure",failure(t)));}
  System.out.println(TerminalNegationOracle.json(result));
 }
}
